  const setActiveScreenTaskTimeoutMinutes = useCallback(
    (activeScreenTaskTimeoutMinutes: number) => {
      const normalizedTimeoutMinutes =
        normalizeActiveScreenTaskTimeoutMinutes(
          activeScreenTaskTimeoutMinutes
        );

      updateSettings((previous) => ({
        ...previous,
        activeScreenTaskTimeoutMinutes: normalizedTimeoutMinutes,
      }));

      const activeScreenTask =
        contextManagerRef.current.getState().taskRuntime.screenAttachment;

      if (activeScreenTask) {
        const now = Date.now();
        const updatedScreenTask = {
          ...activeScreenTask,
          updatedAt: now,
          expiresAt: now + normalizedTimeoutMinutes * 60_000,
        };
        const activeInterviewTask =
          contextManagerRef.current.getState().taskRuntime.parent;
        const updatedInterviewTask =
          activeInterviewTask?.source === "screen"
            ? {
                ...activeInterviewTask,
                updatedAt: now,
                expiresAt: now + normalizedTimeoutMinutes * 60_000,
              }
            : activeInterviewTask;
        submitTaskRuntimeTransition(contextManagerRef.current, {
          transition: "update-source-attachment",
          reason: "active-screen-task-timeout-updated",
          screenAttachment: updatedScreenTask,
          parent: updatedInterviewTask,
        });
        const contextState = contextManagerRef.current.getState();
        setState((previous) => ({
          ...previous,
          taskRuntime: contextState.taskRuntime,
          activeMeetingTask: contextState.activeMeetingTask,
        }));
      }
    },
    [updateSettings]
  );

